const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),empty=()=>Object.fromEntries(Object.keys(RES).map(k=>[k,0]));
function random(s){s.seed=(s.seed*1664525+1013904223)>>>0;return s.seed/4294967296;}
function has(s,id){return !!s.buildings.find(b=>b.id===id)?.built;}
function tech(s){let out={housing:0,heating:0,weapon:1,turret:0,research:s.stage+1};for(let b of s.buildings)if(b.built){out.housing=Math.max(out.housing,b.housingTier||0);out.heating=Math.max(out.heating,b.heatTier||0);out.weapon=Math.max(out.weapon,b.weaponTier||0);out.turret=Math.max(out.turret,b.turretTier||0);}out.city=Math.min(out.housing,out.heating);return out;}
function phase(s){if(s.chapter){let age=s.time-s.chapterAt,tier=age>=175?9:age>=80?8:7;return {at:s.chapterAt+(tier===9?175:tier===8?80:0),tier,coldTier:tier,name:tier===9?'巨兽永夜':tier===8?'大陆寒灾':'远征准备',temp:tier===9?-145:tier===8?-125:-105};}return PHASES.reduce((p,n)=>s.time>=n.at?n:p,PHASES[0]);}
function capacity(s){return has(s,'automata')?360:has(s,'megafactory')?240:has(s,'belt')?150:has(s,'sled')?90:has(s,'tools')?44:24;}
function load(s){return Object.values(s.player.bag).reduce((a,b)=>a+b,0);}
function speed(s){return has(s,'freightport')?390:has(s,'belt')?250:has(s,'sled')?220:185;}
function log(s,text){s.logs.push({text,time:s.time});if(s.logs.length>10)s.logs.shift();event(s,'notice',{text});}
function event(s,type,data={}){if(s.events.length<180)s.events.push({type,...data});}
function active(s,b){return !b.built&&b.stage<=s.stage;}
function worldBounds(s){return s.stage>=6?{maxX:3450,maxY:1600}:s.stage<2?{maxX:1120,maxY:945}:{maxX:1840,maxY:945};}
function deliveryRate(s,remote=false){return has(s,'frontierFabricator')?(remote?2400:3000):has(s,'freightport')?(remote?1500:1800):has(s,'automata')?(remote?720:900):has(s,'megafactory')?(remote?420:520):has(s,'belt')?(remote?115:180):remote?45:65;}
function finalDeadline(s){return (s.chapter?s.chapterAt+FRONTIER_FINAL_AT:FINAL_AT)+(isDebug(s)?s.debug.finalDelay:0);}
function finalDuration(s){return s.chapter?FRONTIER_DURATION:FINAL_DURATION;}
