let debugPaused=isDebug(s)&&s.debug.pauseWaves;if(debugPaused){s.nextRaid+=dt;s.debug.finalDelay+=dt;if(s.finalStarted)s.finalNext+=dt;}let finalAt=finalDeadline(s);
if(!debugPaused&&!s.endless&&!s.finalStarted&&s.time>=finalAt){s.finalStarted=true;s.finalLeft=finalDuration(s);if(!s.chapter)s.stats.finalAt=finalAt;s.finalNext=finalAt;log(s,s.chapter?'大陆终潮按远征时钟抵达：陆地巨兽先至，20 秒后北海巨兽现身。':isDebug(s)?'DEBUG 自动终潮开始：暂停刷怪期间已顺延，守住 90 秒增援后清除余敌。':'16:00 · 终潮按时抵达。守住 90 秒持续增援，再清除所有余敌！');if(s.chapter)spawnBeast(s);event(s,'final');}
